Here is the complete Apps Script. It processes everything in memory and writes the results in a single batch, so it will run on your ~420 rows in about a second. 

It is completely **idempotent**: you can run it, move new items from `ParkMapPending` into `ParkMap`, and run it again as many times as you like without creating duplicate columns or duplicate pending rows.

### How to install and run
1. In your Google Sheet, make sure your main data tab is named **`Raw`** (or change the `RAW_SHEET` constant at the top of the script to match your tab name).
2. Click **Extensions > Apps Script**.
3. Delete any code in the editor, paste the script below, and click **Save** (the floppy disk icon).
4. Refresh your Google Sheet. A new menu called **Volunteer Data** will appear at the top.
5. Click **Volunteer Data > Run Cleaning Script** (it will ask for permission the first time you run it).

```javascript
/**
 * Volunteer Survey Data Cleaner
 * Idempotent script: safe to run repeatedly.
 */

const RAW_SHEET = 'Raw';
const MAP_SHEET = 'ParkMap';
const PENDING_SHEET = 'ParkMapPending';
const DUP_WINDOW_MINS = 10;

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Volunteer Data')
    .addItem('Run Cleaning Script', 'cleanVolunteerData')
    .addToUi();
}

function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const rawSheet = ss.getSheetByName(RAW_SHEET);

  if (!rawSheet) {
    SpreadsheetApp.getUi().alert(`Sheet "${RAW_SHEET}" not found. Please check the tab name.`);
    return;
  }

  // 1. Load or initialize ParkMap
  let mapSheet = ss.getSheetByName(MAP_SHEET);
  if (!mapSheet) {
    mapSheet = ss.insertSheet(MAP_SHEET);
    mapSheet.getRange(1, 1, 5, 2).setValues([
      ['Key', 'Canonical'],
      ['westside', 'West Side'],
      ['wside', 'West Side'],
      ['northpark', 'North Park'],
      ['northpk', 'North Park']
    ]);
  }
  const mapValues = mapSheet.getDataRange().getValues();
  const parkMap = new Map();
  for (let i = 1; i < mapValues.length; i++) {
    const key = String(mapValues[i][0]).trim().toLowerCase();
    const val = String(mapValues[i][1]).trim();
    if (key && val) parkMap.set(key, val);
  }

  // 2. Load or initialize ParkMapPending
  let pendingSheet = ss.getSheetByName(PENDING_SHEET);
  if (!pendingSheet) {
    pendingSheet = ss.insertSheet(PENDING_SHEET);
    pendingSheet.getRange(1, 1, 1, 2).setValues([['Unmapped Key', 'Sample Raw Text']]);
  }
  const pendingValues = pendingSheet.getDataRange().getValues();
  const existingPending = new Set();
  for (let i = 1; i < pendingValues.length; i++) {
    const key = String(pendingValues[i][0]).trim().toLowerCase();
    if (key) existingPending.add(key);
  }

  // 3. Read Raw Data (Columns A:F)
  const lastRow = rawSheet.getLastRow();
  if (lastRow < 2) return; // No data rows

  const rawData = rawSheet.getRange(2, 1, lastRow - 1, 6).getValues();
  const newPendingRows = [];

  // Pass 1: Normalize individual fields & build lookup keys
  const parsedRows = rawData.map((row, idx) => {
    const [rawTs, rawName, rawEmail, rawYN, rawPhone, rawPark] = row;

    // G: Normalize Y/N
    const ynStr = String(rawYN || '').trim().toLowerCase();
    let cleanYN = 'REVIEW';
    if (/^y(es)?$/.test(ynStr)) cleanYN = 'Yes';
    else if (/^no?$/.test(ynStr)) cleanYN = 'No';

    // H: Standardize Phone
    const phoneStr = String(rawPhone || '').trim();
    let digits = phoneStr.replace(/\D/g, '');
    if (digits.length === 11 && digits.startsWith('1')) {
      digits = digits.substring(1);
    }
    const cleanPhone = (digits.length === 10) ? digits : 'REVIEW';

    // I: Standardize Timestamp
    let cleanTs = 'REVIEW';
    let tsMs = null;
    if (rawTs instanceof Date && !isNaN(rawTs.getTime())) {
      cleanTs = rawTs;
      tsMs = rawTs.getTime();
    } else if (String(rawTs || '').trim() !== '') {
      const parsedDate = new Date(String(rawTs).trim());
      if (!isNaN(parsedDate.getTime())) {
        cleanTs = parsedDate;
        tsMs = parsedDate.getTime();
      }
    }

    // J: Consolidate Park Names
    const parkStr = String(rawPark || '').trim();
    const parkKey = parkStr.toLowerCase().replace(/[^a-z]/g, '');
    let cleanPark = 'REVIEW';

    if (parkKey) {
      if (parkMap.has(parkKey)) {
        cleanPark = parkMap.get(parkKey);
      } else if (!existingPending.has(parkKey)) {
        existingPending.add(parkKey);
        newPendingRows.push([parkKey, parkStr]);
      }
    }

    // K & L: Helper Keys
    const emailKey = String(rawEmail || '').trim().toLowerCase();
    const nameKey = String(rawName || '').trim().toLowerCase().replace(/\s+/g, ' ');

    return {
      idx,
      cleanYN,
      cleanPhone,
      cleanTs,
      tsMs,
      cleanPark,
      emailKey,
      nameKey
    };
  });

  // Pass 2: Evaluate Duplicates & Final Review Flag
  const emailCounts = new Map();
  const maxEmailTs = new Map();

  // First, gather counts and latest timestamp per email
  parsedRows.forEach(r => {
    if (r.emailKey) {
      emailCounts.set(r.emailKey, (emailCounts.get(r.emailKey) || 0) + 1);
      if (r.tsMs !== null) {
        const currentMax = maxEmailTs.get(r.emailKey);
        if (currentMax === undefined || r.tsMs > currentMax) {
          maxEmailTs.set(r.emailKey, r.tsMs);
        }
      }
    }
  });

  const windowMs = DUP_WINDOW_MINS * 60 * 1000;

  // Build final output array for Columns G:P
  const outputRows = parsedRows.map((r, i) => {
    // M: DUP-email
    const dupEmail = (r.emailKey && emailCounts.get(r.emailKey) > 1) ? 'DUP-email' : '';

    // N: DUP-name-time (same name within 10 mins)
    let dupNameTime = '';
    if (r.nameKey && r.tsMs !== null) {
      const hasNearMatch = parsedRows.some((other, j) => 
        i !== j && 
        other.nameKey === r.nameKey && 
        other.tsMs !== null && 
        Math.abs(r.tsMs - other.tsMs) <= windowMs
      );
      if (hasNearMatch) dupNameTime = 'DUP-name-time';
    }

    // O: SUPERSEDED (keep most recent per email; also breaks exact timestamp ties)
    let superseded = '';
    if (r.emailKey && emailCounts.get(r.emailKey) > 1 && r.tsMs !== null) {
      const maxTs = maxEmailTs.get(r.emailKey);
      if (r.tsMs < maxTs) {
        superseded = 'SUPERSEDED';
      } else if (r.tsMs === maxTs) {
        // If two rows have the exact same email and max timestamp, supersede the earlier row index
        const hasLaterRowWithSameMaxTs = parsedRows.some((other, j) => 
          j > i && other.emailKey === r.emailKey && other.tsMs === maxTs
        );
        if (hasLaterRowWithSameMaxTs) superseded = 'SUPERSEDED';
      }
    }

    // P: Master Review Flag
    const needsReview = (
      r.cleanYN === 'REVIEW' ||
      r.cleanPhone === 'REVIEW' ||
      r.cleanTs === 'REVIEW' ||
      r.cleanPark === 'REVIEW' ||
      dupEmail !== '' ||
      dupNameTime !== ''
    );
    const reviewFlag = needsReview ? 'REVIEW' : 'OK';

    return [
      r.cleanYN,      // G
      r.cleanPhone,   // H
      r.cleanTs,      // I
      r.cleanPark,    // J
      r.emailKey,     // K
      r.nameKey,      // L
      dupEmail,       // M
      dupNameTime,    // N
      superseded,     // O
      reviewFlag      // P
    ];
  });

  // 4. Write Headers and Data to Raw Sheet (Columns G:P)
  const headers = [[
    'Clean_YN', 'Clean_Phone', 'Clean_Timestamp', 'Clean_Park', 
    'Key_Email', 'Key_Name', 'Flag_DupEmail', 'Flag_DupNameTime', 
    'Flag_Superseded', 'Review_Status'
  ]];

  rawSheet.getRange(1, 7, 1, 10).setValues(headers).setFontWeight('bold');

  // Format Phone column (H) as Plain Text so leading zeros aren't stripped, and Timestamp (I) as datetime
  rawSheet.getRange(2, 8, outputRows.length, 1).setNumberFormat('@');
  rawSheet.getRange(2, 9, outputRows.length, 1).setNumberFormat('yyyy-mm-dd hh:mm');

  // Write all helper columns at once
  rawSheet.getRange(2, 7, outputRows.length, 10).setValues(outputRows);

  // 5. Append any newly discovered unmapped parks to ParkMapPending
  if (newPendingRows.length > 0) {
    const nextPendingRow = pendingSheet.getLastRow() + 1;
    pendingSheet.getRange(nextPendingRow, 1, newPendingRows.length, 2).setValues(newPendingRows);
  }

  SpreadsheetApp.flush();
  SpreadsheetApp.getUi().alert(
    `Cleaning complete!\n\n` +
    `Rows processed: ${outputRows.length}\n` +
    `New unmapped parks added to ${PENDING_SHEET}: ${newPendingRows.length}`
  );
}
```

