/**
 * Volunteer Survey Data Cleaner
 * Idempotent script: preserves manual edits in G2:Q (updates only blank or 'REVIEW' cells).
 */

const RAW_SHEET = 'Raw';
const MAP_SHEET = 'ParkMap';
const PENDING_SHEET = 'ParkMapPending';
