      cleanPhone,
      formattedPhone,
      cleanTs,
      tsMs,
      cleanPark,
      emailKey,
      nameKey
    };
  });

  // Pass 2: Evaluate Duplicates & Final Review Flag
  const emailCounts = new Map();
  const minEmailTs = new Map();

  // Gather counts and EARLIEST timestamp per email
  parsedRows.forEach(r => {
    if (r.emailKey) {
      emailCounts.set(r.emailKey, (emailCounts.get(r.emailKey) || 0) + 1);
      if (r.tsMs !== null) {
        const currentMin = minEmailTs.get(r.emailKey);
        if (currentMin === undefined || r.tsMs < currentMin) {
          minEmailTs.set(r.emailKey, r.tsMs);
        }
      }
    }
  });

  const windowMs = DUP_WINDOW_MINS * 60 * 1000;

  // Counters for Summary Sheet
  let countOK = 0;
  let countReview = 0;
  let countDupEmail = 0;
  let countDupNameTime = 0;
  let countSuperseded = 0;
  const distinctParks = new Set();

  // Build final output array for Columns G:R (12 columns)
  const outputRows = parsedRows.map((r, i) => {
    const existingRow = r.existingRow;

    // O (idx 8): DUP-email
    const compDupEmail = (r.emailKey && emailCounts.get(r.emailKey) > 1) ? 'DUP-email' : '';
    const dupEmail = resolveVal(existingRow[8], compDupEmail);

    // P (idx 9): DUP-name-time (same name within 10 mins)
    let compDupNameTime = '';
    if (r.nameKey && r.tsMs !== null) {
      const hasNearMatch = parsedRows.some((other, j) => 
        i !== j && 
        other.nameKey === r.nameKey && 
        other.tsMs !== null && 
        Math.abs(r.tsMs - other.tsMs) <= windowMs
      );
      if (hasNearMatch) compDupNameTime = 'DUP-name-time';
    }
    const dupNameTime = resolveVal(existingRow[9], compDupNameTime);

    // Q (idx 10): SUPERSEDED (keep earliest per email; mark later ones SUPERSEDED)
    let compSuperseded = '';
    if (r.emailKey && emailCounts.get(r.emailKey) > 1 && r.tsMs !== null) {
      const minTs = minEmailTs.get(r.emailKey);
      if (r.tsMs > minTs) {
        compSuperseded = 'SUPERSEDED';
      } else if (r.tsMs === minTs) {
        const hasEarlierRowWithSameMinTs = parsedRows.some((other, j) => 
          j < i && other.emailKey === r.emailKey && other.tsMs === minTs
        );
        if (hasEarlierRowWithSameMinTs) compSuperseded = 'SUPERSEDED';
      }
    }
    const superseded = resolveVal(existingRow[10], compSuperseded);

    // R (idx 11): Master Review Flag
    const needsReview = (
      String(r.cleanYN).toUpperCase() === 'REVIEW' ||
      String(r.cleanPhone).toUpperCase() === 'REVIEW' ||
      String(r.formattedPhone).toUpperCase() === 'REVIEW' ||
      String(r.cleanTs).toUpperCase() === 'REVIEW' ||
      String(r.cleanPark).toUpperCase() === 'REVIEW' ||
      String(dupEmail) !== '' ||
      String(dupNameTime) !== ''
    );
    const compReviewFlag = needsReview ? 'REVIEW' : 'OK';
    const reviewFlag = resolveVal(existingRow[11], compReviewFlag);

    // Tally summary counts
    if (String(reviewFlag).toUpperCase() === 'OK') countOK++;
    if (String(reviewFlag).toUpperCase() === 'REVIEW') countReview++;
    if (String(dupEmail) !== '') countDupEmail++;
    if (String(dupNameTime) !== '') countDupNameTime++;
    if (String(superseded) !== '') countSuperseded++;

    const parkVal = String(r.cleanPark ?? '').trim();
    if (parkVal !== '' && parkVal.toUpperCase() !== 'REVIEW') {
      distinctParks.add(parkVal);
    }

    return [
      r.cleanYN,        // G
      r.rawPhoneCopy,   // H (Raw Phone Copy)
      r.cleanPhone,     // I (Standardized Phone - 10 digits)
      r.formattedPhone, // J (Formatted Phone - (123) 456-7890)
      r.cleanTs,        // K
      r.cleanPark,      // L
      r.emailKey,       // M
      r.nameKey,        // N
      dupEmail,         // O
      dupNameTime,      // P
      superseded,       // Q
      reviewFlag        // R
    ];
  });

  // 4. Write Headers (only if missing) and Data to Raw Sheet (Columns G:R)
  const defaultHeaders = [
    'Clean_YN', 'Raw_Phone_Copy', 'Clean_Phone', 'Formatted_Phone', 
    'Clean_Timestamp', 'Clean_Park', 'Key_Email', 'Key_Name', 
    'Flag_DupEmail', 'Flag_DupNameTime', 'Flag_Superseded', 'Review_Status'
  ];

  const headerRange = rawSheet.getRange(1, 7, 1, 12);
  const existingHeaders = headerRange.getValues()[0];
  let headersUpdated = false;

  const mergedHeaders = existingHeaders.map((cellVal, idx) => {
    if (String(cellVal).trim() === '') {
      headersUpdated = true;
      return defaultHeaders[idx];
    }
    return cellVal;
  });

  if (headersUpdated) {
    headerRange.setValues([mergedHeaders]).setFontWeight('bold');
  }

  // Format Phone columns (H, I, J -> cols 8, 9, 10) as Plain Text, and Timestamp (K -> col 11) as datetime
  rawSheet.getRange(2, 8, outputRows.length, 3).setNumberFormat('@');
  rawSheet.getRange(2, 11, outputRows.length, 1).setNumberFormat('yyyy-mm-dd hh:mm');

  // Write all helper columns at once
  rawSheet.getRange(2, 7, outputRows.length, 12).setValues(outputRows);

  // 5. Append any newly discovered unmapped parks to ParkMapPending
  if (newPendingRows.length > 0) {
    const nextPendingRow = pendingSheet.getLastRow() + 1;
    pendingSheet.getRange(nextPendingRow, 1, newPendingRows.length, 2).setValues(newPendingRows);
  }

  // 6. Create or Update Summary Sheet (Idempotent overwrite)
  let summarySheet = ss.getSheetByName(SUMMARY_SHEET);
  if (!summarySheet) {
    summarySheet = ss.insertSheet(SUMMARY_SHEET);
  }

  const summaryData = [
    ['Metric', 'Value'],
    ['Last Run Timestamp', new Date()],
    ['Total rows processed', outputRows.length],
    ['Count OK', countOK],
    ['Count REVIEW', countReview],
    ['Count DUP-email', countDupEmail],
    ['Count DUP-name-time', countDupNameTime],
    ['Count SUPERSEDED', countSuperseded],
    ['New unmapped parks added this run', newPendingRows.length],
    ['Count of distinct mapped parks', distinctParks.size]
  ];

  summarySheet.getRange(1, 1, summaryData.length, 2).setValues(summaryData);
  summarySheet.getRange(1, 1, 1, 2).setFontWeight('bold');
  summarySheet.getRange(2, 2).setNumberFormat('yyyy-mm-dd hh:mm:ss');
  summarySheet.autoResizeColumns(1, 2);

  SpreadsheetApp.flush();
  SpreadsheetApp.getUi().alert(
    `Cleaning complete!\n\n` +
    `Rows processed: ${outputRows.length}\n` +
    `OK: ${countOK} | REVIEW: ${countReview}\n` +
    `Distinct mapped parks: ${distinctParks.size}\n` +
    `New unmapped parks added to ${PENDING_SHEET}: ${newPendingRows.length}`
  );
}
